// 1️⃣  Match every player to the teams they have played for
MATCH (p:Player)-[:playsFor]->(t:Team)

// 2️⃣  Follow the historical division‑membership relationship
//      (Assuming the graph stores a time‐sensitive relationship such as
//       :teamDivisionHistory or a timestamped :partOfDivision).
//      If the relationship is called :teamDivisionHistory, use it directly;
//      otherwise, it is represented as :partOfDivision with nullable
//      startDate / endDate properties.
//      The following pattern uses both possibilities via an OPTIONAL
//      OPTIONAL MATCH – it will work with either implementation.
OPTIONAL MATCH (t)-[h1:teamDivisionHistory|:partOfDivision]->(d:Division)

// 3️⃣  Keep only historical memberships that were in the Central Division
WHERE d.name = "Central Division"

// 4️⃣  Aggregate distinct team names per player
WITH p.name AS playerName, collect(distinct t.name) AS teams

// 5️⃣  Return the player name and the count of distinct Central‑division
//      teams they have been a member of, ordered by that count descending
RETURN playerName, size(teams) AS teamCount
ORDER BY teamCount DESC;

